// -----------------------------------------------------------------------------
// The MOSMIX station table (data/stations.json, generated by
// scripts/update-stations.mjs): the nearest forecast point of a location,
// and the nearest station that publishes hourly observations.
// -----------------------------------------------------------------------------

import { readFileSync } from 'node:fs';
import { distanceKm } from './geo.js';

let table;

function load() {
  if (!table) {
    const file = JSON.parse(
      readFileSync(new URL('../data/stations.json', import.meta.url), 'utf8'),
    );
    table = file.stations.map(([id, name, latitude, longitude, elevation, observed]) => ({
      id,
      name,
      latitude,
      longitude,
      elevation,
      observed: observed === 1,
    }));
  }
  return table;
}

/** Every station (read once). */
export function allStations() {
  return load();
}

export function findStation(id) {
  return load().find((station) => station.id === id);
}

/**
 * Nearest station of a location, among those matching `filter`, with its
 * distance; undefined when none is within `maxKm`.
 */
export function nearestStation(latitude, longitude, { filter, maxKm = Infinity } = {}) {
  let best;
  for (const station of load()) {
    if (filter && !filter(station)) {
      continue;
    }
    // Cheap pre-filter: one degree of latitude is 111 km.
    if (Math.abs(station.latitude - latitude) * 111 > maxKm) {
      continue;
    }
    const distance = distanceKm(latitude, longitude, station.latitude, station.longitude);
    if (distance <= maxKm && (!best || distance < best.distance)) {
      best = { ...station, distance };
    }
  }
  return best;
}
